import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  // Auth & UI States
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [authData, setAuthData] = useState({ username: '', password: '' });
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS"); // Fixed: HDFC Bank default for Accuracy Proof
  const [loading, setLoading] = useState(false);

  // 🟢 Final Indian Stock List (As per Google Finance)
  const stockList = [
    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },
    { name: "JSW Steel", symbol: "JSWSTEEL.NS" },
    { name: "HDFC Life", symbol: "HDFCLIFE.NS" },
    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },
    { name: "Paytm (One97)", symbol: "PAYTM.NS" },
    { name: "Zomato", symbol: "ZOMATO.NS" },
    { name: "Sun Pharma", symbol: "SUNPHARMA.NS" },
    { name: "ITC", symbol: "ITC.NS" }
  ];

  const handleAuth = async () => {
    // Endpoints-a prefix kooda check pannikonga
    const endpoint = isSignup ? "/auth/signup" : "/auth/login";
    try {
      const res = await axios.post(`http://localhost:8000${endpoint}`, authData);
      if (isSignup) {
        alert("Signup Success! Now please Login.");
        setIsSignup(false);
      } else {
        setIsLoggedIn(true);
      }
    } catch (err) {
      console.error(err);
      alert("Error: " + (err.response?.data?.detail || "Connection Failed"));
    }
  };
  // Analyze Logic
  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend Error", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    if (isLoggedIn) {
      fetchData(selectedStock);
    }
  }, [selectedStock, isLoggedIn]);

  // --- LOGIN SCREEN ---
  if (!isLoggedIn) {
    return (
      <div style={{ backgroundColor: '#0d1117', height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', color: 'white', fontFamily: 'monospace' }}>
        <div style={{ background: '#161b22', padding: '40px', borderRadius: '10px', border: '1px solid #30363d', width: '350px' }}>
          <h2 style={{ textAlign: 'center', color: '#58a6ff' }}>🛡️ QuantShield {isSignup ? "Signup" : "Login"}</h2>
          <input type="text" placeholder="Username" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: '#0d1117', border: '1px solid #30363d', color: 'white', borderRadius: '5px' }} />
          <input type="password" placeholder="Password" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: '#0d1117', border: '1px solid #30363d', color: 'white', borderRadius: '5px' }} />
          <button onClick={handleAuth} style={{ width: '100%', padding: '12px', background: '#238636', color: 'white', border: 'none', borderRadius: '5px', cursor: 'pointer', fontWeight: 'bold' }}>
            {isSignup ? "CREATE ACCOUNT" : "SIGN IN"}
          </button>
          <p onClick={() => setIsSignup(!isSignup)} style={{ textAlign: 'center', marginTop: '15px', cursor: 'pointer', color: '#58a6ff' }}>
            {isSignup ? "Already have an account? Login" : "New User? Register here"}
          </p>
        </div>
      </div>
    );
  }

  // --- DASHBOARD SCREEN ---
  return (
    <div style={{ backgroundColor: '#0d1117', minHeight: '100vh', padding: '20px', color: '#c9d1d9', fontFamily: 'monospace' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '10px', marginBottom: '20px' }}>
        <h2 style={{ color: '#58a6ff' }}>🛡️ AI Portfolio Optimizer</h2>
        <button onClick={() => setIsLoggedIn(false)} style={{ background: '#f85149', color: 'white', border: 'none', padding: '5px 15px', borderRadius: '5px', cursor: 'pointer' }}>LOGOUT</button>
      </div>

      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '20px' }}>
        <label style={{ fontWeight: 'bold', color: '#8b949e' }}>📂 ACTIVE ASSET: </label>
        <select value={selectedStock} onChange={(e) => setSelectedStock(e.target.value)} style={{ background: '#0d1117', color: 'white', border: '1px solid #58a6ff', padding: '10px', borderRadius: '5px', width: '350px' }}>
          {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name}</option>)}
        </select>
        {loading && <span style={{ marginLeft: '10px', color: '#f1e05a' }}>⚡ Syncing...</span>}
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '10px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#f85149', marginTop: 0 }}>📊 Market Proof</h3>
            <div style={{ background: '#0d1117', padding: '20px', textAlign: 'center', borderRadius: '10px', border: '1px solid #58a6ff', marginBottom: '15px' }}>
              <span style={{ fontSize: '10px', color: '#8b949e' }}>CURRENT PRICE</span>
              <h1 style={{ color: '#58a6ff', margin: '5px 0' }}>₹{data.current_price}</h1>
            </div>
            <p>Volatility: <b style={{ float: 'right', color: '#f85149' }}>{data.volatility}</b></p>
            <p>Regime: <b style={{ float: 'right' }}>{data.regime}</b></p>
            <div style={{ marginTop: '20px', padding: '15px', textAlign: 'center', background: data.regime === "STRESS" ? '#4a151b' : '#064e3b', borderRadius: '5px', fontWeight: 'bold' }}>
              🛡️ GHOST HEDGE: {data.regime === "STRESS" ? "ACTIVE" : "MONITORING"}
            </div>
          </div>

          <div style={{ background: '#161b22', padding: '20px', borderRadius: '10px', border: '1px solid #30363d' }}>
            <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', marginBottom: '15px' }}>
              <h4 style={{ color: '#f1e05a', margin: 0 }}>🔮 2-DAY FORECAST</h4>
              <p>Day 2: <b>₹{data.prediction?.day2}</b> <span style={{ color: data.prediction?.trend === "UP" ? '#3fb950' : '#f85149' }}>({data.prediction?.pct})</span></p>
            </div>
            
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
              <div style={{ background: '#0d1117', padding: '15px', borderLeft: '5px solid #238636' }}>
                <span style={{ fontSize: '12px' }}>Expected Return</span>
                <h2 style={{ color: '#3fb950' }}>₹{data.forecast?.expected}</h2>
              </div>
              <div style={{ background: '#0d1117', padding: '15px', borderLeft: '5px solid #f85149' }}>
                <span style={{ fontSize: '12px' }}>Worst Case Scene</span>
                <h2 style={{ color: '#f85149' }}>₹{data.forecast?.worst_case}</h2>
              </div>
            </div>

            <div style={{ marginTop: '30px', padding: '25px', textAlign: 'center', borderRadius: '10px', background: data.decision === "BUY" ? '#238636' : data.decision === "AVOID" ? '#f85149' : '#f1e05a', color: 'white', fontSize: '26px', fontWeight: 'bold' }}>
              🤖 AI VERDICT: {data.decision}
            </div>
            
          </div>

        </div>
      )}
    </div>
  );
}

export default App;
